record ActivityEvent(UUID eventId,UUID spaceId,UUID actorId,String traceId,String occurredAt,String kind,String eventType,String aggregateType,UUID aggregateId,long sourceVersion,UUID roadmapId,UUID nodeId,String title,String nodeTitle,String state,String detail,String startedAt,String endedAt,long durationSeconds,String targetPath,Planning planning,Content content,Note note,NoteConcepts noteConcepts,Metadata metadata,NoteLinks noteLinks,NoteAttachments noteAttachments,Claim claim){
 ActivityEvent(UUID eventId,UUID spaceId,UUID actorId,String traceId,String occurredAt,String kind,String eventType,String aggregateType,UUID aggregateId,long sourceVersion,UUID roadmapId,UUID nodeId,String title,String nodeTitle,String state,String detail,String startedAt,String endedAt,long durationSeconds,String targetPath,Planning planning,Content content,Note note,NoteConcepts noteConcepts,Metadata metadata,NoteLinks noteLinks,NoteAttachments noteAttachments){this(eventId,spaceId,actorId,traceId,occurredAt,kind,eventType,aggregateType,aggregateId,sourceVersion,roadmapId,nodeId,title,nodeTitle,state,detail,startedAt,endedAt,durationSeconds,targetPath,planning,content,note,noteConcepts,metadata,noteLinks,noteAttachments,null);}
 record Claim(UUID revisionId,UUID subjectConceptId,UUID predicateConceptId,ClaimObject object,String verificationState){}
 @com.fasterxml.jackson.annotation.JsonInclude(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL)
 record ClaimObject(String type,UUID conceptId,String value){}
 record Attachment(UUID attachmentId,UUID mediaId,String filename,String mimeType,long byteSize,String sha256){}
 record NoteAttachments(UUID revisionId,long noteVersion,List<Attachment> attachments){}
 record WikiLink(UUID linkId,int ordinal,int startOffset,int endOffset,String targetToken,UUID requestedTargetId,String label,String fragment,UUID targetNoteId,String status){}
 record NoteLinks(UUID revisionId,long noteVersion,List<WikiLink> links){}
 record Tag(UUID tagId,String name){}
 record Property(UUID propertyId,String name,String type,String jsonValue){}
 record Metadata(UUID revisionId,long noteVersion,List<Tag> tags,List<Property> properties){}
 record NoteConcepts(UUID revisionId,long noteVersion,List<Link> concepts){}
 record Note(UUID revisionId,String journalDate,String timeZone,int markdownBytes,boolean truncated){}
 static boolean note(String kind){return Set.of("NOTE","DAILY_NOTE").contains(kind);}
 record Link(UUID linkId,UUID conceptId){}
 record Content(String recordType,UUID recordId,long recordVersion,String status,String url,String answer,String outcome,String rationale,String alternatives,List<Link> concepts){}
 static boolean content(String kind){return Set.of("BOOKMARK","QUESTION","DECISION","RECORD_CONCEPTS").contains(kind);}
 record Planning(String status,String date,UUID goalId,UUID taskId,String startsAt,String endsAt,String timeZone,String startsLocal,String endsLocal,String startsOffset,String endsOffset){}
 static boolean planning(String kind){return Set.of("GOAL","TASK","SCHEDULE").contains(kind);}
 static String group(String kind){if(kind.equals("GITHUB_COMMIT")||GitHubWorkActivity.kind(kind))return "integration";return kind.equals("CLAIM")?"knowledge":kind.equals("NOTE_ATTACHMENTS")||kind.equals("NOTE_LINKS")||kind.equals("NOTE_METADATA")||kind.equals("NOTE_CONCEPTS")||note(kind)||content(kind)?"content":planning(kind)?"planning":"learning";}
 static boolean target(ActivityEvent e){if(GitHubWorkActivity.kind(e.kind()))return GitHubWorkActivity.target(e);if(GitHubLearningActivity.kind(e.kind()))return GitHubLearningActivity.target(e);if(e.kind().equals("GITHUB_COMMIT"))return GitHubActivity.target(e);if(e.kind().equals("CLAIM"))return ClaimActivity.target(e);if(e.claim()!=null)return false;if(e.kind().equals("NOTE_ATTACHMENTS"))return AttachmentActivity.target(e);if(e.kind().equals("NOTE_LINKS"))return NoteLinkActivity.target(e);if(e.kind().equals("NOTE_METADATA"))return MetadataActivity.target(e);if(e.kind().equals("NOTE_CONCEPTS"))return NoteConceptActivity.target(e);if(note(e.kind()))return NoteActivity.target(e);if(content(e.kind()))return ContentActivity.target(e);if(planning(e.kind()))return e.roadmapId()==null&&e.nodeId()==null&&e.planning()!=null&&e.targetPath().equals("/api/spaces/"+e.spaceId()+"/"+e.kind().toLowerCase(java.util.Locale.ROOT)+"s/"+e.aggregateId());return e.roadmapId()!=null&&e.planning()==null&&e.targetPath().startsWith("/api/spaces/"+e.spaceId()+"/roadmaps/"+e.roadmapId());}
 static final Map<String,String> TOPICS=Map.ofEntries(Map.entry("GITHUB_ISSUE","integration.github-issue.v1"),Map.entry("GITHUB_PULL_REQUEST","integration.github-pull-request.v1"),Map.entry("GITHUB_EVIDENCE","learning.github-evidence.v1"),Map.entry("GITHUB_EVIDENCE_SESSION","learning.github-evidence-session.v1"),Map.entry("GITHUB_COMMIT","integration.github-commit.v1"),Map.entry("CLAIM","knowledge.claim.v2"),Map.entry("ROADMAP","learning.roadmap.v1"),Map.entry("PROGRESS","learning.progress.v1"),Map.entry("STUDY_SESSION","learning.study-session.v1"),Map.entry("NOTE_EVIDENCE","learning.evidence.v1"),Map.entry("CONCEPT_EVIDENCE","learning.concept-evidence.v1"),Map.entry("MEDIA_EVIDENCE","learning.media-evidence.v1"),Map.entry("EVIDENCE_SESSION","learning.evidence-session.v1"),Map.entry("GOAL","planning.goal.v1"),Map.entry("TASK","planning.task.v1"),Map.entry("SCHEDULE","planning.schedule.v1"),Map.entry("BOOKMARK","content.bookmark.v1"),Map.entry("QUESTION","content.question.v1"),Map.entry("DECISION","content.decision.v1"),Map.entry("RECORD_CONCEPTS","content.record-concepts.v1"),Map.entry("NOTE","content.note.v1"),Map.entry("DAILY_NOTE","content.daily-note.v1"),Map.entry("NOTE_CONCEPTS","content.note-concepts.v1"),Map.entry("NOTE_METADATA","content.note-metadata.v1"),Map.entry("NOTE_LINKS","content.note-links.v1"),Map.entry("NOTE_ATTACHMENTS","content.note-attachments.v1"));
 static final Map<String,String> ARTIFACTS=Map.ofEntries(Map.entry("GITHUB_ISSUE","github-issue-events"),Map.entry("GITHUB_PULL_REQUEST","github-pull-request-events"),Map.entry("GITHUB_EVIDENCE","github-evidence-events"),Map.entry("GITHUB_EVIDENCE_SESSION","github-evidence-session-events"),Map.entry("GITHUB_COMMIT","github-commit-events"),Map.entry("CLAIM","claim-events-v2"),Map.entry("ROADMAP","roadmap-events"),Map.entry("PROGRESS","progress-events"),Map.entry("STUDY_SESSION","study-session-events"),Map.entry("NOTE_EVIDENCE","evidence-events"),Map.entry("CONCEPT_EVIDENCE","concept-evidence-events"),Map.entry("MEDIA_EVIDENCE","media-evidence-events"),Map.entry("EVIDENCE_SESSION","evidence-session-events"),Map.entry("GOAL","goal-events"),Map.entry("TASK","task-events"),Map.entry("SCHEDULE","schedule-events"),Map.entry("BOOKMARK","bookmark-events"),Map.entry("QUESTION","question-events"),Map.entry("DECISION","decision-events"),Map.entry("RECORD_CONCEPTS","record-concepts-events"),Map.entry("NOTE","note-events"),Map.entry("DAILY_NOTE","daily-note-events"),Map.entry("NOTE_CONCEPTS","note-concepts-events"),Map.entry("NOTE_METADATA","note-metadata-events"),Map.entry("NOTE_LINKS","note-links-events"),Map.entry("NOTE_ATTACHMENTS","note-attachments-events"));
 static Set<String> topics(){var topics=new HashSet<>(TOPICS.values());topics.add("knowledge.claim.v1");return Set.copyOf(topics);}
 static IllegalArgumentException invalid(){return new IllegalArgumentException("Invalid activity event");}
 static UUID id(String s){try{var id=UUID.fromString(s);if(id.version()!=7||id.variant()!=2||!id.toString().equals(s))throw invalid();return id;}catch(RuntimeException e){throw invalid();}}
 private static String text(String s,int max,boolean required){if(s==null||(required&&s.isBlank())||s.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>max||s.codePoints().anyMatch(c->Character.isISOControl(c)&&c!='\n'&&c!='\r'&&c!='\t')||s.codePoints().anyMatch(c->c>=0xd800&&c<=0xdfff))throw invalid();return s;}
 static ActivityEvent decode(String topic,byte[] wire){if(wire==null||wire.length<1||wire.length>1048576)throw invalid();String kind=topic.equals("knowledge.claim.v1")?"CLAIM":TOPICS.entrySet().stream().filter(e->e.getValue().equals(topic)).map(Map.Entry::getKey).findFirst().orElseThrow(ActivityEvent::invalid);try{
  var e=RoadmapEventEnvelopeV1.parseFrom(wire);UUID event=id(e.getEventId()),space=id(e.getSpaceId()),actor=id(e.getActorId()),aggregate=id(e.getAggregateId());if(e.getEventVersion()!=(topic.equals("knowledge.claim.v2")?2:1)||!e.getProducer().equals(group(kind)+"-service")||e.getOccurredAtEpochMillis()<1||!e.getTraceId().matches("[0-9a-f]{32}")||e.getTraceId().equals("0".repeat(32)))throw invalid();if(GitHubWorkActivity.kind(kind))return GitHubWorkActivity.decode(e,kind);if(GitHubLearningActivity.kind(kind))return GitHubLearningActivity.decode(e,kind);if(kind.equals("GITHUB_COMMIT"))return GitHubActivity.decode(e);if(kind.equals("CLAIM"))return ClaimActivity.decode(e,topic.endsWith(".v1"));if(kind.equals("NOTE_ATTACHMENTS"))return AttachmentActivity.decode(e);if(kind.equals("NOTE_LINKS"))return NoteLinkActivity.decode(e);if(kind.equals("NOTE_METADATA"))return MetadataActivity.decode(e);if(kind.equals("NOTE_CONCEPTS"))return NoteConceptActivity.decode(e);if(note(kind))return NoteActivity.decode(e,kind);if(content(kind))return ContentActivity.decode(e,kind);if(planning(kind))return PlanningActivity.decode(e,kind);UUID roadmap,node=null;long version;String title="",nodeTitle="",state,detail="",start=null,end=null,suffix,aggregateType;long duration=0;Set<String> types;
  switch(kind){
   case "ROADMAP"->{var p=RoadmapChangedPayloadV1.parseFrom(e.getPayload());if(!aggregate.equals(id(p.getRoadmapId()))||!p.getVisibility().equals("PRIVATE"))throw invalid();id(p.getRevisionId());roadmap=aggregate;version=p.getVersion();title=text(p.getTitle(),800,true);state=p.getState();suffix="";aggregateType="Roadmap";types=Set.of("RoadmapCreated","RoadmapUpdated","RoadmapGraphChanged","RoadmapRetired");}
   case "PROGRESS"->{var p=ProgressChangedPayloadV1.parseFrom(e.getPayload());if(!aggregate.equals(id(p.getProgressId()))||!p.getVisibility().equals("PRIVATE"))throw invalid();id(p.getRevisionId());roadmap=id(p.getRoadmapId());node=id(p.getNodeId());version=p.getVersion();state=p.getStatus();if(!Set.of("NOT_STARTED","IN_PROGRESS","COMPLETED").contains(state))throw invalid();title="학습 진도";suffix="/nodes/"+node+"/progress";aggregateType="LearningProgress";types=Set.of("LearningProgressChanged");}
   case "STUDY_SESSION"->{var p=StudySessionChangedPayloadV1.parseFrom(e.getPayload());if(!aggregate.equals(id(p.getSessionId()))||!p.getVisibility().equals("PRIVATE"))throw invalid();id(p.getRevisionId());roadmap=id(p.getRoadmapId());node=id(p.getNodeId());version=p.getVersion();nodeTitle=text(p.getNodeTitle(),800,true);title=nodeTitle;state=p.getState();detail=text(p.getNote(),8192,false);start=p.getStartedAt();end=p.getEndedAt();duration=p.getDurationSeconds();suffix="/study-sessions/"+aggregate;aggregateType="StudySession";types=Set.of("StudySessionRecorded","StudySessionUpdated","StudySessionRetired");}
   case "NOTE_EVIDENCE"->{var p=EvidenceChangedPayloadV1.parseFrom(e.getPayload());if(!aggregate.equals(id(p.getEvidenceId()))||!p.getVisibility().equals("PRIVATE")||p.getNoteVersion()<1)throw invalid();id(p.getNoteId());id(p.getRevisionId());roadmap=id(p.getRoadmapId());node=id(p.getNodeId());version=p.getVersion();nodeTitle=text(p.getNodeTitle(),800,true);title=text(p.getNoteTitle(),800,true);state=p.getState();detail=text(p.getMemo(),8192,false);suffix="/evidence/"+aggregate;aggregateType="LearningEvidence";types=Set.of("LearningEvidenceLinked","LearningEvidenceUpdated","LearningEvidenceRetired");}
   case "CONCEPT_EVIDENCE"->{var p=ConceptEvidenceChangedPayloadV1.parseFrom(e.getPayload());if(!aggregate.equals(id(p.getEvidenceId()))||!p.getVisibility().equals("PRIVATE")||p.getConceptVersion()<1||!(p.getConceptVisibility().equals("PUBLIC")||p.getConceptVisibility().equals("PRIVATE")&&p.getConceptSpaceId().equals(space.toString())))throw invalid();id(p.getConceptId());id(p.getConceptSpaceId());id(p.getRevisionId());roadmap=id(p.getRoadmapId());node=id(p.getNodeId());version=p.getVersion();nodeTitle=text(p.getNodeTitle(),800,true);title=text(p.getConceptTitle(),800,true);state=p.getState();detail=text(p.getMemo(),8192,false);suffix="/concept-evidence/"+aggregate;aggregateType="ConceptLearningEvidence";types=Set.of("ConceptLearningEvidenceLinked","ConceptLearningEvidenceUpdated","ConceptLearningEvidenceRetired");}
   case "MEDIA_EVIDENCE"->{var p=MediaEvidenceChangedPayloadV1.parseFrom(e.getPayload());if(!aggregate.equals(id(p.getEvidenceId()))||!p.getVisibility().equals("PRIVATE")||p.getMediaVersion()<1||p.getByteSize()<1||p.getByteSize()>10485760||!p.getSha256().matches("[0-9a-f]{64}"))throw invalid();id(p.getMediaId());id(p.getRevisionId());roadmap=id(p.getRoadmapId());node=id(p.getNodeId());version=p.getVersion();nodeTitle=text(p.getNodeTitle(),800,true);title=text(p.getMediaFilename(),800,true);state=p.getState();detail=text(p.getMemo(),8192,false);suffix="/media-evidence/"+aggregate;aggregateType="MediaLearningEvidence";types=Set.of("MediaLearningEvidenceLinked","MediaLearningEvidenceUpdated","MediaLearningEvidenceRetired");}
   case "EVIDENCE_SESSION"->{var p=EvidenceSessionChangedPayloadV1.parseFrom(e.getPayload());if(!aggregate.equals(id(p.getLinkId()))||!p.getVisibility().equals("PRIVATE"))throw invalid();id(p.getRevisionId());roadmap=id(p.getRoadmapId());node=id(p.getNodeId());version=p.getVersion();nodeTitle=text(p.getNodeTitle(),800,true);title=nodeTitle;state=p.getState();String type=switch(p.getEvidenceKind()){case "NOTE"->"evidence";case "CONCEPT"->"concept-evidence";case "MEDIA"->"media-evidence";default->throw invalid();};suffix="/"+type+"/"+id(p.getEvidenceId())+"/study-session";if(state.equals("LINKED")){id(p.getSessionId());if(p.getSessionVersion()<1)throw invalid();start=p.getStartedAt();end=p.getEndedAt();duration=p.getDurationSeconds();}else if(!state.equals("UNLINKED")||!p.getSessionId().isEmpty()||p.getSessionVersion()!=0||!p.getStartedAt().isEmpty()||!p.getEndedAt().isEmpty()||p.getDurationSeconds()!=0)throw invalid();aggregateType="EvidenceStudySession";types=Set.of("EvidenceStudySessionChanged");}
   default->throw invalid();
  }
  if(version<1||!types.contains(e.getEventType())||!aggregateType.equals(e.getAggregateType()))throw invalid();if(!Set.of("PROGRESS","EVIDENCE_SESSION").contains(kind)&&!Set.of("ACTIVE","RETIRED").contains(state))throw invalid();if(start!=null&&(duration<1||duration>86400||!Instant.parse(end).equals(Instant.parse(start).plusSeconds(duration))))throw invalid();return new ActivityEvent(event,space,actor,e.getTraceId(),Instant.ofEpochMilli(e.getOccurredAtEpochMillis()).toString(),kind,e.getEventType(),aggregateType,aggregate,version,roadmap,node,title,nodeTitle,state,detail,start,end,duration,"/api/spaces/"+space+"/roadmaps/"+roadmap+suffix,null,null,null,null,null,null,null);
 }catch(com.google.protobuf.InvalidProtocolBufferException|java.time.DateTimeException ex){throw invalid();}}
 static void transport(String topic,byte[] wire,String key,Map<String,String> headers){var event=decode(topic,wire);if(!event.aggregateId().toString().equals(key)||!event.eventId().toString().equals(headers.get("id"))||!group(event.kind()).equals(headers.get("schema_group"))||!(topic.equals("knowledge.claim.v1")?"claim-events":ARTIFACTS.get(event.kind())).equals(headers.get("schema_artifact"))||!"1".equals(headers.get("schema_version"))||!event.traceId().equals(headers.get("trace_id")))throw invalid();}
}
